<script>
(function(){
    var rows=[].slice.call(document.querySelectorAll('.academic-note-row')), status=document.getElementById('notes-import-status');
    [].forEach.call(document.querySelectorAll('form[method=get] select'),function(s){s.addEventListener('change',function(){document.getElementById('academic-grades-form').querySelector('button[type=submit],button:not([type])').disabled=true;status.textContent='Le contexte a changé : cliquez sur « Afficher » avant de saisir les notes.';});});
    function csvCell(v){v=String(v||'');if(/^[=+@\-\t\r]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"';}
    document.getElementById('notes-template').addEventListener('click',function(){var lines=['id_eleve;matricule;note;anonymat;mois'];rows.forEach(function(r){lines.push([r.dataset.id,r.dataset.matricule,'','',''].map(csvCell).join(';'));});var url=URL.createObjectURL(new Blob(['\uFEFF'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}));var a=document.createElement('a');a.href=url;a.download='modele_notes_tutelle.csv';a.click();setTimeout(function(){URL.revokeObjectURL(url);},1000);});
    function parse(text){var delimiter=text.split(/\r?\n/)[0].indexOf(';')>=0?';':',', result=[],line=[],field='',quoted=false;for(var i=0;i<text.length;i++){var c=text[i];if(c==='"'){if(quoted && text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c===delimiter && !quoted){line.push(field);field='';}else if((c==='\n'||c==='\r')&&!quoted){line.push(field);if(line.some(function(v){return v.trim()!=='';}))result.push(line);line=[];field='';if(c==='\r'&&text[i+1]==='\n')i++;}else field+=c;}if(quoted)throw Error('Guillemets non fermés.');line.push(field);if(line.some(function(v){return v.trim()!=='';}))result.push(line);return result;}
    document.getElementById('notes-file').addEventListener('change',function(){var file=this.files[0];if(!file)return;var reader=new FileReader();reader.onload=function(){try{var data=parse(String(reader.result).replace(/^\uFEFF/,''));if(!data.length)throw Error('Fichier vide.');var headers=data.shift().map(function(v){return v.trim().toLowerCase();}), noteIndex=headers.indexOf('note'),idIndex=headers.indexOf('id_eleve'),matIndex=headers.indexOf('matricule'),anonIndex=headers.indexOf('anonymat'),monthIndex=headers.indexOf('mois');if(noteIndex<0 || (idIndex<0&&matIndex<0))throw Error('Colonnes requises : note et id_eleve ou matricule.');var updates=[],seen={};data.forEach(function(values,i){var raw=(values[noteIndex]||'').trim();if(raw==='')return;var id=idIndex>=0?(values[idIndex]||'').trim():'',mat=matIndex>=0?(values[matIndex]||'').trim():'',matches=rows.filter(function(r){return id?r.dataset.id===id:mat && r.dataset.matricule===mat;});if(matches.length!==1 || (mat&&matches[0].dataset.matricule!==mat))throw Error('Ligne '+(i+2)+' : étudiant absent ou ambigu dans cette classe.');var row=matches[0],number=Number(raw.replace(',','.'));if(!Number.isFinite(number)||number<0||number>20)throw Error('Ligne '+(i+2)+' : note hors de 0 à 20.');if(seen[row.dataset.id])throw Error('Étudiant en double dans le fichier, ligne '+(i+2)+'.');seen[row.dataset.id]=true;updates.push({row:row,note:number,anonymat:anonIndex>=0?values[anonIndex]:undefined,mois:monthIndex>=0?values[monthIndex]:undefined});});updates.forEach(function(u){u.row.querySelector('.note-input').value=u.note;if(u.anonymat!==undefined)u.row.querySelector('.anonymat-input').value=u.anonymat;if(u.mois!==undefined)u.row.querySelector('.mois-input').value=u.mois;});status.textContent=updates.length+' note(s) préparée(s). Vérifiez la liste puis enregistrez.';}catch(e){status.textContent='Import arrêté : '+e.message;}};reader.readAsText(file,'UTF-8');});
})();
</script>
